<template>
  <section class="ops-layout">
    <div class="panel ops-main">
      <div class="ops-head"><div><h2>SQL Account 匯出批次</h2><p>目前採標準匯入檔模式；完成代表檔案已產生，不代表已在 SQL Account 入帳。</p></div><button @click="loadData">重新載入</button></div>
      <div class="mode-banner"><strong>目前接入模式：標準 CSV 匯入檔</strong><span>待確認 SQL Account 版本及接口後，只需替換後端 Adapter。</span></div>
      <div v-if="loading" class="ops-state">正在讀取同步資料…</div>
      <div v-else-if="errorMessage" class="ops-state error"><strong>同步資料載入失敗</strong><span>{{ errorMessage }}</span><button @click="loadData">重試</button></div>
      <div v-else class="table-wrap ops-table">
        <table><thead><tr><th>批次號</th><th>資料範圍</th><th>總筆數</th><th>成功</th><th>失敗</th><th>狀態</th><th>建立人</th><th>完成時間</th><th>操作</th></tr></thead>
          <tbody><tr v-for="batch in filteredBatches" :key="batch.id" :class="{ selected: selectedId === batch.id }" @click="selectedId = batch.id">
            <td><strong>{{ batch.batchNo }}</strong><small>{{ batch.triggerMode === 'manual' ? '手動建立' : batch.triggerMode }}</small></td><td>{{ moduleLabel(batch.sourceModule) }}</td><td>{{ batch.totalCount }}</td><td class="success-text">{{ batch.successCount }}</td><td :class="{ 'danger-text': batch.failureCount }">{{ batch.failureCount }}</td><td><span class="ops-tag" :class="batch.status">{{ statusLabel(batch.status) }}</span></td><td>{{ batch.createdByName || '系統' }}</td><td>{{ dateTime(batch.completedAt) }}</td><td class="row-actions"><button v-if="['exported','partial'].includes(batch.status)" @click.stop="download(batch)">下載</button><button v-if="batch.failureCount" @click.stop="retry(batch)">重試</button></td>
          </tr><tr v-if="!filteredBatches.length"><td colspan="9" class="empty-cell">尚無符合條件的匯出批次</td></tr></tbody>
        </table>
      </div>
    </div>
    <aside class="panel ops-detail">
      <template v-if="selectedBatch"><div class="detail-title"><div class="detail-icon">SQL</div><div><h3>{{ selectedBatch.batchNo }}</h3><p>{{ moduleLabel(selectedBatch.sourceModule) }}</p></div><span class="ops-tag" :class="selectedBatch.status">{{ statusLabel(selectedBatch.status) }}</span></div>
        <div class="detail-actions"><button :disabled="!['exported','partial'].includes(selectedBatch.status)" @click="download(selectedBatch)">下載匯入檔</button><button :disabled="!selectedBatch.failureCount" @click="retry(selectedBatch)">重試失敗</button></div>
        <section class="detail-section"><h4>批次統計</h4><dl><div><dt>總記錄</dt><dd>{{ selectedBatch.totalCount }}</dd></div><div><dt>已匯出</dt><dd>{{ selectedBatch.successCount }}</dd></div><div><dt>失敗</dt><dd>{{ selectedBatch.failureCount }}</dd></div><div><dt>完成時間</dt><dd>{{ dateTime(selectedBatch.completedAt) }}</dd></div></dl></section>
        <section class="detail-section item-list"><h4>批次明細</h4><article v-for="item in selectedItems" :key="item.id"><div><strong>{{ item.transactionNo || `記錄 #${item.entityId}` }}</strong><small>{{ item.externalId || item.errorMessage || '等待處理' }}</small></div><span class="ops-tag" :class="item.status">{{ statusLabel(item.status) }}</span></article><p v-if="!selectedItems.length">尚無明細</p></section>
      </template><div v-else class="ops-state">選擇一個批次查看明細</div>
    </aside>

    <dialog ref="syncDialog" class="ops-dialog"><form @submit.prevent="createBatch"><header><div><h3>建立 SQL Account 匯出批次</h3><p>先預覽資料，再產生可交付的標準 CSV。</p></div><button type="button" @click="closeDialog">×</button></header>
      <div class="dialog-body"><label>資料範圍<select v-model="form.sourceModule" @change="preview = null"><option value="all">全部已確認交易</option><option value="property_payment">房款收款</option><option value="rent_payment">租金收款</option><option value="reserve">預備金充值與扣款</option><option value="cashflow">收支記錄</option></select></label>
        <button type="button" class="preview-button" :disabled="previewing" @click="loadPreview">{{ previewing ? '預覽中…' : '預覽待匯出資料' }}</button>
        <section v-if="preview" class="preview-card"><div><span>符合條件</span><strong>{{ preview.eligibleCount }} 筆</strong></div><div><span>總金額</span><strong>RM {{ money(preview.totalAmount) }}</strong></div><p v-for="warning in preview.warnings" :key="warning">{{ warning }}</p><div class="preview-list"><article v-for="item in preview.items.slice(0,8)" :key="item.id"><span>{{ item.transactionNo }}</span><b>{{ item.partyName }}</b><strong>RM {{ money(item.amount) }}</strong></article></div></section>
        <p v-if="dialogError" class="dialog-error">{{ dialogError }}</p></div><menu><button type="button" @click="closeDialog">取消</button><button class="save-button" :disabled="creating || !preview?.eligibleCount">{{ creating ? '產生中…' : '建立並產生 CSV' }}</button></menu>
    </form></dialog>
  </section>
</template>

<script>
import { createAdminSyncBatch, downloadAdminSyncBatch, fetchAdminSync, previewAdminSync, retryAdminSyncBatch } from '../services/propertyApi';
export default {
  inject: ['page'], data() { return { loading: true, errorMessage: '', batches: [], items: [], selectedId: null, form: { sourceModule: 'all', recordIds: [] }, preview: null, previewing: false, creating: false, dialogError: '' }; },
  computed: {
    keyword() { return String(this.page.globalSearch || this.page.moduleSearch || '').trim().toLowerCase(); },
    filteredBatches() { const status = this.page.statusFilter; return this.batches.filter(b => (!this.keyword || `${b.batchNo} ${this.moduleLabel(b.sourceModule)} ${b.createdByName || ''}`.toLowerCase().includes(this.keyword)) && (!status || status.includes('全部') || (status === '處理中' && b.status === 'processing') || (status === '已匯出' && b.status === 'exported') || (status === '同步失敗' && b.status === 'failed'))); },
    selectedBatch() { return this.batches.find(b => b.id === this.selectedId) || this.filteredBatches[0] || null; }, selectedItems() { return this.items.filter(i => i.batchId === this.selectedBatch?.id); },
    createNonce() { return this.page.adminSyncCreateNonce; }, refreshNonce() { return this.page.adminSyncRefreshNonce; }
  },
  watch: { createNonce(v,p){if(v>p)this.openDialog();}, refreshNonce(v,p){if(v>p)this.loadData();}, filteredBatches(rows){if(!rows.some(r=>r.id===this.selectedId))this.selectedId=rows[0]?.id||null;} },
  mounted() { this.page.projectFilter = '全部批次'; this.page.statusFilter = '全部狀態'; this.loadData(); },
  methods: {
    async loadData(){this.loading=true;this.errorMessage='';try{const r=await fetchAdminSync();this.batches=r.batches||[];this.items=r.items||[];if(!this.batches.some(b=>b.id===this.selectedId))this.selectedId=this.batches[0]?.id||null;this.setMetrics(r.summary||{});this.setExport();}catch(e){this.errorMessage=e.message||'同步資料載入失敗';this.page.adminSyncMetrics=null;}finally{this.loading=false;}},
    setMetrics(s){this.page.adminSyncMetrics=[{label:'待匯出交易',value:`${Number(s.eligibleCount||0)} 筆`,delta:'已確認且尚未同步',trend:Number(s.eligibleCount)?'down':'up'},{label:'已產生匯入檔',value:`${Number(s.exportedCount||0)} 筆`,delta:'等待 SQL Account 匯入',trend:'up'},{label:'失敗交易',value:`${Number(s.failedCount||0)} 筆`,delta:'可建立重試批次',trend:Number(s.failedCount)?'down':'up'},{label:'同步批次',value:`${Number(s.batchCount||0)} 個`,delta:`共 ${Number(s.itemCount||0)} 筆明細`,trend:'up'}];},
    setExport(){this.page.adminSyncExportHeaders=['批次號','資料範圍','總筆數','成功','失敗','狀態','建立人','完成時間'];this.page.adminSyncExportRows=this.batches.map(b=>[b.batchNo,this.moduleLabel(b.sourceModule),b.totalCount,b.successCount,b.failureCount,this.statusLabel(b.status),b.createdByName||'',this.dateTime(b.completedAt)]);},
    openDialog(){this.form={sourceModule:'all',recordIds:[]};this.preview=null;this.dialogError='';this.$refs.syncDialog?.showModal();},closeDialog(){if(!this.creating)this.$refs.syncDialog?.close();},
    async loadPreview(){this.previewing=true;this.dialogError='';try{this.preview=await previewAdminSync(this.form);}catch(e){this.dialogError=e.message||'預覽失敗';}finally{this.previewing=false;}},
    async createBatch(){this.creating=true;this.dialogError='';try{const b=await createAdminSyncBatch(this.form);this.selectedId=b.id;this.$refs.syncDialog?.close();await this.loadData();this.page.showToast(`匯出批次 ${b.batchNo} 已建立`);}catch(e){this.dialogError=e.message||'批次建立失敗';}finally{this.creating=false;}},
    async retry(batch){try{const result=await retryAdminSyncBatch(batch.id);await this.loadData();this.selectedId=result.id;this.page.showToast('失敗項目已重新匯出');}catch(e){this.page.showToast(e.message||'重試失敗');}},
    async download(batch){try{const f=await downloadAdminSyncBatch(batch.id);this.saveBlob(f.blob,`${batch.batchNo}.csv`);}catch(e){this.page.showToast(e.message||'下載失敗');}},saveBlob(blob,name){const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;a.click();URL.revokeObjectURL(u);},
    moduleLabel(v){return({all:'全部交易',property_payment:'房款收款',rent_payment:'租金收款',reserve:'預備金',cashflow:'收支記錄'})[v]||v;},statusLabel(v){return({processing:'處理中',exported:'已匯出',failed:'失敗',partial:'部分完成',success:'成功',pending:'待處理'})[v]||v;},dateTime(v){return v?String(v).replace('T',' ').slice(0,16):'—';},money(v){return Number(v||0).toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2});}
  }
};
</script>
<style scoped>
.ops-layout{display:grid;grid-template-columns:minmax(0,1fr) 350px;gap:14px;min-height:570px}.ops-main,.ops-detail{min-width:0}.ops-head{display:flex;align-items:center;justify-content:space-between;padding:16px 18px 10px}.ops-head h2{margin:0 0 4px;font-size:18px}.ops-head p{margin:0;color:#6d7d90;font-size:12px}.ops-head button,.preview-button{border:1px solid #ccd7e4;border-radius:6px;background:#fff;padding:7px 11px;color:#0a477c}.mode-banner{display:flex;justify-content:space-between;gap:15px;margin:0 18px 10px;padding:10px 12px;border:1px solid #efd18c;border-radius:8px;background:#fff8e8;color:#795700;font-size:12px}.ops-table{overflow:auto}.ops-table table{min-width:1000px}.ops-table tr{cursor:pointer}.ops-table tr.selected{background:#fff8e8}.ops-table td strong,.ops-table td small{display:block}.ops-table td small{margin-top:3px;color:#718096;font-size:11px}.ops-tag{display:inline-flex;padding:4px 8px;border:1px solid;border-radius:6px;font-size:11px}.ops-tag.exported,.ops-tag.success{color:#168348;background:#edf9f1;border-color:#b9e4c7}.ops-tag.processing,.ops-tag.pending{color:#a56600;background:#fff7e5;border-color:#eed08c}.ops-tag.failed,.ops-tag.partial{color:#c5313b;background:#fff0f1;border-color:#efbbc0}.success-text{color:#158149}.danger-text,.dialog-error{color:#c5303a}.row-actions{white-space:nowrap}.row-actions button{margin-right:4px;border:1px solid #ccd7e4;border-radius:5px;background:#fff;padding:5px 8px;color:#0a477c}.empty-cell{text-align:center;color:#718096;padding:35px!important}.ops-detail{padding:17px}.detail-title{display:grid;grid-template-columns:48px 1fr auto;align-items:center;gap:10px}.detail-icon{display:grid;place-items:center;width:48px;height:48px;border-radius:12px;background:#0b3c70;color:#fff;font-weight:800}.detail-title h3{margin:0 0 4px;font-size:15px}.detail-title p{margin:0;color:#718096}.detail-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:15px 0}.detail-actions button{border:1px solid #ccd7e4;border-radius:6px;background:#fff;padding:8px;color:#0a477c}.detail-actions button:first-child{background:#0a3c70;color:#fff}.detail-actions button:disabled{opacity:.5}.detail-section{padding:14px 0;border-top:1px solid #e2e8ef}.detail-section h4{margin:0 0 10px}.detail-section dl{margin:0}.detail-section dl div{display:flex;justify-content:space-between;padding:5px 0}.detail-section dt{color:#718096}.detail-section dd{margin:0;font-weight:600}.item-list{max-height:320px;overflow:auto}.item-list article{display:flex;justify-content:space-between;gap:8px;padding:8px 0;border-bottom:1px dashed #dfe6ed}.item-list strong,.item-list small{display:block}.item-list small{margin-top:3px;color:#718096;font-size:10px}.ops-state{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;min-height:280px;color:#718096}.ops-state.error strong{color:#c5303a}.ops-dialog{width:min(650px,calc(100vw - 32px));padding:0;border:0;border-radius:12px;box-shadow:0 22px 70px #10233b42}.ops-dialog::backdrop{background:#0a172a80}.ops-dialog form{margin:0}.ops-dialog header{display:flex;justify-content:space-between;padding:20px 22px;border-bottom:1px solid #e1e7ee}.ops-dialog h3{margin:0 0 5px}.ops-dialog header p{margin:0;color:#718096;font-size:12px}.ops-dialog header button{border:0;background:transparent;font-size:26px}.dialog-body{display:grid;gap:13px;max-height:65vh;padding:20px 22px;overflow:auto}.dialog-body label{display:grid;gap:6px;font-weight:600}.dialog-body select{border:1px solid #ccd7e3;border-radius:7px;padding:10px}.preview-card{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:13px;border-radius:8px;background:#f5f8fb}.preview-card>div>span,.preview-card>div>strong{display:block}.preview-card>div>strong{margin-top:4px;font-size:18px}.preview-card>p{grid-column:1/-1;margin:0;color:#a66700;font-size:12px}.preview-list{grid-column:1/-1}.preview-list article{display:grid;grid-template-columns:1fr 1fr auto;gap:8px;padding:6px 0;border-top:1px dashed #d9e1e9;font-size:11px}.ops-dialog menu{display:flex;justify-content:flex-end;gap:8px;margin:0;padding:14px 22px;background:#f6f8fb}.ops-dialog menu button{border:1px solid #ccd7e3;border-radius:7px;background:#fff;padding:9px 16px}.ops-dialog menu .save-button{background:#cf8900;border-color:#cf8900;color:#fff}.ops-dialog menu button:disabled{opacity:.5}@media(max-width:1200px){.ops-layout{grid-template-columns:1fr}}@media(max-width:650px){.mode-banner{flex-direction:column}.preview-card{grid-template-columns:1fr}}
</style>
